def priority(item, bins):
    """Harmonic heuristic: group bins by remaining capacity into intervals and score based on item size."""
    # Define harmonic intervals (based on 1/k fractions of capacity)
    # Intervals: (0, 50], (50, 66.7], (66.7, 75], (75, 80], (80, 83.3], (83.3, 100]
    intervals = [50, 66.6667, 75, 80, 83.3333, 100]

    # Determine which interval the item fits best in (prefer larger remaining capacity)
    item_interval = 0
    for i, threshold in enumerate(intervals):
        if item <= threshold:
            item_interval = i
            break

    # Score: prefer bins whose remaining capacity is in the same or slightly larger interval
    # than the item, with a small random perturbation for tie-breaking
    scores = np.zeros_like(bins)
    for i, r in enumerate(bins):
        bin_interval = 0
        for j, threshold in enumerate(intervals):
            if r <= threshold:
                bin_interval = j
                break
        # Prefer bins with interval close to item's interval, but slightly larger is better
        if bin_interval == item_interval:
            scores[i] = 10.0  # Perfect match
        elif bin_interval == item_interval + 1:
            scores[i] = 8.0   # Slightly larger
        elif bin_interval == item_interval - 1:
            scores[i] = 6.0   # Slightly smaller
        elif bin_interval > item_interval:
            scores[i] = 4.0   # Much larger (wasteful but safe)
        else:
            scores[i] = 2.0   # Much smaller (tight fit)
        # Add small bias for tighter fit within same interval
        scores[i] += 0.1 * (r - item) / r if r > 0 else 0
    return scores
